// 1. Get Webhook Data
const webhookData = $('GPS Webhook').first().json.body;
const currentStep = parseInt(webhookData.currentStep || 0);
const userLat = parseFloat(webhookData.lat || 0);
const userLng = parseFloat(webhookData.lng || 0);

// 2. Get Target Data from your specific MySQL Node
const target = $('Execute a SQL query1').first().json;

// 3. Haversine Formula for distance
function getDistance(lat1, lon1, lat2, lon2) {
  const R = 6371e3; 
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

// 4. Game Logic
const distance = getDistance(target.lat, target.lng, userLat, userLng);
const isFound = distance < 100; // 100m success radius

let systemPrompt = "";
let nextStep = currentStep;

if (isFound) {
  nextStep += 1;
  systemPrompt = `You are 'Control', a secret agent handler. The agent just transmitted their GPS coordinates and successfully reached the target: ${target.name}. Congratulate them. Be dramatic. Tell them we are preparing the next mission coordinates.`;
} else {
  systemPrompt = `You are 'Control', a secret agent handler. The agent transmitted their GPS coordinates, but they are currently ${Math.round(distance)} meters away from the target. Tell them they are in the wrong sector and encourage them to keep searching. Target intel: ${target.base_clue}. CRITICAL: Do NOT use the target's name.`;
}

return {
  found: isFound,
  newStep: nextStep,
  systemPrompt: systemPrompt,
  photo: $('GPS Webhook').first().binary 
    ? $('GPS Webhook').first().binary[Object.keys($('GPS Webhook').first().binary)[0]].data 
    : null
};

